"""Instructions plus the actual application schema, without sample-project bias."""
import json
from pathlib import Path
from app.core.models import AgentExtractionResult


def report_output_schema():
    schema = AgentExtractionResult.model_json_schema()
    # Runner, database and reviewer fields must not be generated by the model.
    for field in ('source_metrics', 'inspected_files', 'jira_context', 'verification_report'):
        schema['properties'].pop(field, None)
    return schema


AGENT_SYSTEM_PROMPT = (
    Path(__file__).with_name('report_authoring.md').read_text(encoding='utf-8')
    + '\n\nAUTHORITATIVE OUTPUT JSON SCHEMA\n'
    + json.dumps(report_output_schema(), ensure_ascii=False, indent=2)
)
